import type { ImpactAnalysis, ImpactedEntity } from "../engine/types";

/**
 * Deterministic, versioned proposal rules.
 *
 * Sector-agnostic: these rules reason about graph structure (how many hops,
 * whether evidence resolves), never about teachers or classes. The same rules
 * run unchanged against a logistics or healthcare pack.
 *
 * Nothing here is generated by a model, and nothing is hardcoded to a
 * particular entity. If the graph changes, the proposals change.
 */

export interface ProposalDraft {
  ruleId: string;
  actionType: string;
  targetEntityId: string;
  targetEntityType: string;
  targetEntityName: string;
  rationale: string;
  evidenceStatus: string;
  supported: boolean;
}

export const RULE_COVER_DIRECT = "rule.action.cover-direct-dependency@1";
export const RULE_EVIDENCE_GAP = "rule.action.resolve-evidence-gap@1";

/**
 * Rule 1: a direct dependency loses its provider.
 *
 * An entity one relationship away from the changed entity depends on it with
 * no intermediary absorbing the change, so it needs an explicit replacement
 * decision. Multi-hop dependents are deliberately excluded: they are affected
 * *through* something else, and proposing a separate action for each would
 * manufacture busywork rather than reflect the dependency structure.
 */
function coverDirectDependency(e: ImpactedEntity): ProposalDraft | null {
  if (e.shortestPath.edgeHops !== 1) return null;

  // Do NOT propose an operational change on a finding whose evidence does not
  // resolve. Telling someone to decide a replacement for a dependency we
  // cannot actually evidence is advice built on nothing. The evidence-gap
  // rule still fires for these, so they are surfaced -- just not actioned.
  if (!e.supported || e.evidenceStatus !== "COMPLETE") return null;

  return {
    ruleId: RULE_COVER_DIRECT,
    actionType: "REASSIGN_DEPENDENCY",
    targetEntityId: e.entityId,
    targetEntityType: e.entityType,
    targetEntityName: e.name,
    rationale:
      `"${e.name}" depends directly on the changed entity ` +
      `(1 relationship, ${e.shortestPath.entityHops} organizational transition). ` +
      `A replacement provider must be decided. Evidence: ${e.evidenceStatus}.`,
    evidenceStatus: e.evidenceStatus,
    supported: e.supported,
  };
}

/**
 * Rule 2: the dependency chain cites evidence that does not resolve.
 *
 * This proposes resolving the gap, NOT acting on the unsupported conclusion.
 * It fires only when the graph actually contains a gap, so on a fully
 * evidenced seed it produces nothing -- which is the correct, data-driven
 * outcome rather than a guaranteed demo talking point.
 */
function resolveEvidenceGap(e: ImpactedEntity): ProposalDraft | null {
  if (e.evidenceStatus === "COMPLETE") return null;
  return {
    ruleId: RULE_EVIDENCE_GAP,
    actionType: "RESOLVE_EVIDENCE_GAP",
    targetEntityId: e.entityId,
    targetEntityType: e.entityType,
    targetEntityName: e.name,
    rationale:
      `The dependency chain reaching "${e.name}" has evidence status ` +
      `${e.evidenceStatus}. Unresolved references: ` +
      `${e.unresolvedSourceIds.join(", ") || "none recorded"}. ` +
      `This conclusion is not fully supported and must not be acted on until the gap is closed.`,
    evidenceStatus: e.evidenceStatus,
    supported: e.supported,
  };
}

const RULES = [coverDirectDependency, resolveEvidenceGap];

/**
 * Generate proposals for an analysis. Pure and deterministic: the same
 * analysis always yields the same drafts, in the same order.
 */
export function generateProposals(analysis: ImpactAnalysis): ProposalDraft[] {
  const drafts: ProposalDraft[] = [];
  for (const entity of analysis.impacted) {
    for (const rule of RULES) {
      const draft = rule(entity);
      if (draft) drafts.push(draft);
    }
  }
  return drafts.sort(
    (a, b) =>
      a.ruleId.localeCompare(b.ruleId) || a.targetEntityId.localeCompare(b.targetEntityId),
  );
}
